// ── Canvas generation ──────────────────────────────────────────────────────────

const CW = 1080, CH = 1350;
const RED  = '#CA2331', BLUE = '#082D68', GOLD = '#F0C040', WHITE = '#FFFFFF';
const PX = 30, PY = 220, PW = CW - 60, PH = 900, SR = 52;

function loadImg(url) {
  return new Promise(resolve => {
    const img = new Image();
    img.crossOrigin = 'anonymous';
    const t = setTimeout(() => resolve(null), 6000);
    img.onload  = () => { clearTimeout(t); resolve(img); };
    img.onerror = () => { clearTimeout(t); resolve(null); };
    img.src = url;
  });
}

function surname(player) {
  const s = (player.name || '').split(' ')[0];
  return s.length > 10 ? s.slice(0, 9) + '.' : s;
}

async function generateXICanvas(formation, squad) {
  const slots = FORMATIONS[formation];
  const photos = {};
  await Promise.all(slots.map(async slot => {
    const p = squad[slot.key];
    if (p?.photo) photos[slot.key] = await loadImg(PHOTO_BASE + p.photo);
  }));

  const canvas = document.createElement('canvas');
  canvas.width = CW; canvas.height = CH;
  const ctx = canvas.getContext('2d');

  // Background
  const bg = ctx.createLinearGradient(0, 0, 0, CH);
  bg.addColorStop(0, '#0c1e52'); bg.addColorStop(0.5, BLUE); bg.addColorStop(1, '#071840');
  ctx.fillStyle = bg; ctx.fillRect(0, 0, CW, CH);
  ctx.fillStyle = RED; ctx.fillRect(0, 0, CW, 8);

  // Header
  ctx.font = 'bold 54px sans-serif'; ctx.fillStyle = WHITE; ctx.textAlign = 'center';
  ctx.fillText('ArchivioRossoBlu', CW / 2, 100);
  ctx.font = 'bold 28px sans-serif'; ctx.fillStyle = GOLD;
  ctx.fillText(`Il mio XI di tutti i tempi · ${formation}`, CW / 2, 152);
  ctx.strokeStyle = 'rgba(240,192,64,0.35)'; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(60, 178); ctx.lineTo(CW - 60, 178); ctx.stroke();

  // Pitch
  const pg = ctx.createLinearGradient(PX, PY, PX, PY + PH);
  pg.addColorStop(0, '#1a7a2a'); pg.addColorStop(0.5, '#22922a'); pg.addColorStop(1, '#1a7a2a');
  ctx.fillStyle = pg; ctx.fillRect(PX, PY, PW, PH);
  ctx.fillStyle = 'rgba(0,0,0,0.07)';
  for (let i = 0; i < 10; i += 2) ctx.fillRect(PX, PY + i * (PH / 10), PW, PH / 10);

  // Pitch lines
  ctx.strokeStyle = 'rgba(255,255,255,0.6)'; ctx.lineWidth = 3;
  ctx.strokeRect(PX, PY, PW, PH);
  ctx.beginPath(); ctx.moveTo(PX, PY + PH / 2); ctx.lineTo(PX + PW, PY + PH / 2); ctx.stroke();
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + PH / 2, 78, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = 'rgba(255,255,255,0.6)';
  ctx.beginPath(); ctx.arc(PX + PW / 2, PY + PH / 2, 5, 0, Math.PI * 2); ctx.fill();
  const paw = PW * 0.593, pah = PH * 0.157, paxo = PX + (PW - paw) / 2;
  ctx.strokeRect(paxo, PY, paw, pah); ctx.strokeRect(paxo, PY + PH - pah, paw, pah);
  const gaw = PW * 0.27, gah = PH * 0.052, gaxo = PX + (PW - gaw) / 2;
  ctx.strokeRect(gaxo, PY, gaw, gah); ctx.strokeRect(gaxo, PY + PH - gah, gaw, gah);

  // Players
  for (const slot of slots) {
    const px = PX + (slot.x / 100) * PW;
    const py = PY + (slot.y / 100) * PH;
    const player = squad[slot.key];
    const photo  = photos[slot.key];

    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.5)'; ctx.shadowBlur = 16;
    ctx.beginPath(); ctx.arc(px, py, SR, 0, Math.PI * 2);
    ctx.fillStyle = BLUE; ctx.fill();
    ctx.restore();

    ctx.save();
    ctx.beginPath(); ctx.arc(px, py, SR, 0, Math.PI * 2); ctx.clip();
    if (photo) {
      ctx.drawImage(photo, px - SR, py - SR, SR * 2, SR * 2);
    } else if (player) {
      ctx.fillStyle = BLUE; ctx.fillRect(px - SR, py - SR, SR * 2, SR * 2);
      ctx.font = `bold ${Math.round(SR * 0.6)}px sans-serif`;
      ctx.fillStyle = WHITE; ctx.textAlign = 'center';
      ctx.fillText((player.name || '').charAt(0).toUpperCase(), px, py + SR * 0.25);
    } else {
      ctx.fillStyle = 'rgba(255,255,255,0.12)'; ctx.fillRect(px - SR, py - SR, SR * 2, SR * 2);
    }
    ctx.restore();

    ctx.strokeStyle = player ? GOLD : 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 3;
    ctx.beginPath(); ctx.arc(px, py, SR, 0, Math.PI * 2); ctx.stroke();

    if (player) {
      const label = surname(player);
      ctx.font = 'bold 20px sans-serif'; ctx.textAlign = 'center';
      const tw = ctx.measureText(label).width;
      const tagW = tw + 24, tagH = 28, tagX = px - tagW / 2, tagY = py + SR + 6;
      ctx.fillStyle = 'rgba(0,0,0,0.7)';
      ctx.beginPath();
      ctx.roundRect?.(tagX, tagY, tagW, tagH, 4) || ctx.fillRect(tagX, tagY, tagW, tagH);
      ctx.fill();
      ctx.fillStyle = WHITE; ctx.fillText(label, px, tagY + 20);
    } else {
      ctx.font = 'bold 18px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.5)';
      ctx.textAlign = 'center'; ctx.fillText(slot.label, px, py + 7);
    }
  }

  // Footer
  ctx.font = 'bold 24px sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.45)';
  ctx.textAlign = 'center'; ctx.fillText('archiviorossoblu.it', CW / 2, CH - 30);

  return canvas;
}

