export default function AllTimeXIPage() {
  const classes = useStyles();
  const [formation, setFormation]       = useState('4-3-3');
  const [squad, setSquad]               = useState({});
  const [players, setPlayers]           = useState([]);
  const [pickerOpen, setPickerOpen]     = useState(false);
  const [activeSlot, setActiveSlot]     = useState(null);
  const [search, setSearch]             = useState('');
  const [sharing, setSharing]           = useState(false);
  const [confirmReset, setConfirmReset] = useState(false);
  const [playerStats, setPlayerStats]   = useState({});
  const [openPlayer, setOpenPlayer]     = useState(false);
  const [playerId, setPlayerId]         = useState(0);
  const [playerReport, setPlayerReport] = useState([]);
  const fetchedIds = useRef(new Set());

  useEffect(() => {
    fetch('/allPlayers.json').then(r => r.json()).then(setPlayers);
    try {
      const raw = localStorage.getItem('arb_xi_v1');
      if (raw) {
        const { formation: f, squad: s } = JSON.parse(raw);
        if (f && FORMATIONS[f] && s) { setFormation(f); setSquad(s); }
      }
    } catch {}
  }, []);

  useEffect(() => {
    localStorage.setItem('arb_xi_v1', JSON.stringify({ formation, squad }));
  }, [formation, squad]);

  useEffect(() => {
    FORMATIONS[formation].forEach(s => {
      const player = squad[s.key];
      if (!player) return;
      const id = String(player.id);
      if (fetchedIds.current.has(id)) return;
      fetchedIds.current.add(id);
      ARBApi.getAllByID('playerDetails', player.id).then(r => {
        const seasons = r?.seasons || [];
        const totals = seasons.reduce((acc, s) => ({
          appareances: acc.appareances + (parseInt(s.appareances) > 0 ? parseInt(s.appareances) : 0),
          goal:        acc.goal        + (parseInt(s.goal)        > 0 ? parseInt(s.goal)        : 0),
        }), { appareances: 0, goal: 0 });
        const years = seasons.map(s => s.year).filter(Boolean);
        setPlayerStats(prev => ({ ...prev, [id]: { ...totals, years } }));
      }).catch(() => {
        setPlayerStats(prev => ({ ...prev, [id]: { appareances: 0, goal: 0, years: [] } }));
      });
    });
  }, [squad, formation]);

  const slots        = FORMATIONS[formation];
  const filledCount  = slots.filter(s => squad[s.key]).length;

  const selectedEntries = slots
    .map(s => ({ slot: s, player: squad[s.key] }))
    .filter(x => x.player);
  const statsLoadingCount = selectedEntries.filter(({ player }) => !playerStats[String(player.id)]).length;
  const aggregated = selectedEntries.reduce((acc, { slot, player }) => {
    const s = playerStats[String(player.id)];
    if (!s) return acc;
    (s.years || []).forEach(y => acc.yearSet.add(y));
    return {
      yearSet:       acc.yearSet,
      appareances:   acc.appareances   + s.appareances,
      goalsScored:   acc.goalsScored   + (slot.key === 'gk' ? 0 : s.goal),
      goalsConceded: acc.goalsConceded + (slot.key === 'gk' ? s.goal : 0),
    };
  }, { yearSet: new Set(), appareances: 0, goalsScored: 0, goalsConceded: 0 });

  const sortedYears = [...aggregated.yearSet].sort();
  const seasonCount = sortedYears.length;

  const yearPlayerCount = new Map();
  selectedEntries.forEach(({ player }) => {
    const s = playerStats[String(player.id)];
    (s?.years || []).forEach(y => yearPlayerCount.set(y, (yearPlayerCount.get(y) || 0) + 1));
  });

  const onSelectPlayer = (id) => {
    ARBApi.getAllByID('playerDetails', id).then(report => {
      if (report) { setPlayerReport(report); setPlayerId(id); setOpenPlayer(true); }
    });
  };

  const handleFormationChange = (_, val) => {
    if (!val) return;
    setFormation(val);
    setSquad({});
  };

  const handleSlotClick = (slot) => {
    setActiveSlot(slot);
    setSearch('');
    setPickerOpen(true);
  };

  const handlePlayerSelect = (player) => {
    setSquad(prev => ({ ...prev, [activeSlot.key]: player }));
    setPickerOpen(false);
  };

  const handleRemoveFromPicker = () => {
    setSquad(prev => { const n = { ...prev }; delete n[activeSlot.key]; return n; });
    setPickerOpen(false);
  };

  const handleShare = useCallback(async () => {
    setSharing(true);
    try {
      const canvas = await generateXICanvas(formation, squad);
      const blob   = await new Promise(r => canvas.toBlob(r, 'image/jpeg', 0.92));
      const isMobile = /Mobi|Android|iPhone|iPad/i.test(navigator.userAgent);
      const file = new File([blob], 'arb-xi.jpg', { type: 'image/jpeg' });
      if (isMobile && navigator.canShare?.({ files: [file] })) {
        await navigator.share({ files: [file], title: 'Il mio XI di tutti i tempi – ArchivioRossoBlu' });
      } else {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `arb-xi-${formation}.jpg`; a.click();
        URL.revokeObjectURL(url);
      }
    } catch (e) {
      if (e?.name !== 'AbortError' && e?.message !== 'Share canceled') console.error('Share error:', e);
    } finally {
      setSharing(false);
    }
  }, [formation, squad]);

  const eligiblePlayers = activeSlot?.key === 'gk'
    ? players.filter(p => ROLE_GROUPS['Portiere'].includes(p.role))
    : players;
  const suggested = activeSlot
    ? eligiblePlayers.filter(p => (ROLE_GROUPS[activeSlot.suggestedRole] || []).includes(p.role))
    : [];
  const others = activeSlot
    ? eligiblePlayers.filter(p => !(ROLE_GROUPS[activeSlot.suggestedRole] || []).includes(p.role))
    : [];
  const allFiltered = (search
    ? [...suggested, ...others]
    : []
  ).filter(p => p.name.toLowerCase().includes(search.toLowerCase()));

  return (
    <Box>
      <SEO
        title="XI di tutti i tempi | ArchivioRossoBlu"
        description="Scegli il tuo XI di tutti i tempi del Cagliari Calcio: seleziona i migliori rossoblù della storia e condividilo sui social."
        path="/cagliari-calcio/xi-di-tutti-i-tempi"
      />

      <Card className={classes.navCard}>
        <div className={classes.navHeader}>
          <Sidebar iconColor="#F0C040" />
          <div style={{ display: 'flex', alignItems: 'center', gap: 6, flex: 1 }}>
            <img src="https://www.archiviorossoblu.it/images/sun-gold-sella-bg.png" alt="logo" title="ArchivioRossoBlu"
              style={{ width: 80, height: 80, flexShrink: 0 }} />
            <Typography component="a" href="/cagliari-calcio" className={classes.brand} style={{ flex: 'none' }}>
              <span className="brand-short" title="ArchivioRossoBlu">ARB</span>
              <span className="brand-full">ArchivioRossoBlu</span>
            </Typography>
          </div>
          <YouTubeLink />
          <ShareButtons />
          <Chip label="XI tutti i tempi" size="small" style={{ fontWeight: 700, backgroundColor: '#F0C040', color: '#082D68' }} />
        </div>
        <Divider />
      </Card>

      <Box className={classes.content}>
        <Breadcrumb items={[
          { label: 'Home', href: '/cagliari-calcio' },
          { label: 'XI di tutti i tempi' },
        ]} />

        <Card style={{ borderTop: '4px solid #CA2331', marginBottom: 16 }}>
          <Box style={{ padding: '10px 16px', display: 'flex', alignItems: 'center', gap: 8 }}>
            <SportsSoccerIcon style={{ color: '#082D68', fontSize: '1.2rem' }} />
            <Box>
              <Typography style={{ fontWeight: 700, fontSize: '0.9rem', color: '#082D68', lineHeight: 1.2 }}>
                Il tuo XI di tutti i tempi
              </Typography>
              <Typography variant="caption" style={{ color: 'rgba(0,0,0,0.5)' }}>
                Scegli i migliori 11 rossoblù della storia · {filledCount}/11
              </Typography>
            </Box>
          </Box>
          <Divider />
          <Box style={{ padding: '8px 16px', display: 'flex', flexWrap: 'wrap', gap: '6px 24px' }}>
            {[
              'Tocca un cerchio sul campo per selezionare il giocatore',
              'I ruoli suggeriti vengono mostrati per primi',
              'La formazione viene salvata automaticamente',
              'Usa Condividi per esportare l\'immagine',
            ].map(tip => (
              <Typography key={tip} variant="caption" style={{ color: 'rgba(0,0,0,0.5)', display: 'flex', alignItems: 'center', gap: 4 }}>
                <span style={{ color: '#082D68', fontWeight: 700 }}>·</span> {tip}
              </Typography>
            ))}
          </Box>
        </Card>

        <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start', flexWrap: { xs: 'wrap', sm: 'nowrap' } }}>
          {/* Pitch */}
          <Card sx={{ flex: '0 0 auto', width: { xs: '100%', sm: 420, md: 480 } }}>
            <CardContent sx={{ pb: '8px !important', display: 'flex', flexDirection: 'column', height: '100%', boxSizing: 'border-box' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                <Typography variant="caption" sx={{ fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                  Modulo
                </Typography>
                <ToggleButtonGroup value={formation} exclusive onChange={handleFormationChange} size="small">
                  {Object.keys(FORMATIONS).map(f => (
                    <ToggleButton key={f} value={f} sx={{ fontSize: 11, px: 1, py: 0.3, fontWeight: 700 }}>
                      {f}
                    </ToggleButton>
                  ))}
                </ToggleButtonGroup>
              </Box>

              <Box className={classes.pitch}>
                <svg className={classes.pitchSvg} viewBox="0 0 100 100" preserveAspectRatio="none">
                  {[0,2,4,6,8].map(i => (
                    <rect key={i} x="0" y={i * 10} width="100" height="10" fill="rgba(0,0,0,0.05)"/>
                  ))}
                  <rect x="0.5" y="0.5" width="99" height="99" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="0.6"/>
                  <line x1="0.5" y1="0.5" x2="99.5" y2="0.5" stroke="rgba(255,255,255,0.5)" strokeWidth="1.2"/>
                  <rect x="20.5" y="68" width="59" height="31.5" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="0.6"/>
                  <rect x="36.5" y="89.5" width="27" height="10" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="0.6"/>
                  <circle cx="50" cy="79" r="1.2" fill="rgba(255,255,255,0.5)"/>
                  <path d="M 37 68 A 17 17 0 0 0 63 68" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="0.6"/>
                </svg>
                {slots.map(slot => (
                  <PlayerSlot
                    key={slot.key}
                    slot={slot}
                    player={squad[slot.key]}
                    onClick={() => handleSlotClick(slot)}
                  />
                ))}
              </Box>

              <Box sx={{ display: 'flex', justifyContent: 'flex-end', gap: 1, mt: 'auto', pt: 1, mb: 0.5 }}>
                <Button size="small" color="error" startIcon={<RestartAltIcon />}
                  onClick={() => setConfirmReset(true)} disabled={filledCount === 0}>
                  Reset
                </Button>
                <Button size="small" variant="contained" color="secondary"
                  startIcon={sharing ? <CircularProgress size={14} color="inherit" /> : <IosShareIcon />}
                  onClick={handleShare} disabled={sharing || filledCount === 0}>
                  Condividi
                </Button>
              </Box>
            </CardContent>
          </Card>

          {/* Right column: Stats + Seasons */}
          <Box sx={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 2 }}>
          <Card>
            <CardContent sx={{ py: '8px !important' }}>
              <Typography variant="caption" sx={{ fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '0.06em', display: 'block', mb: 0.5 }}>
                Stats al Cagliari
              </Typography>

              {filledCount === 0 ? (
                <Typography variant="caption" sx={{ color: 'text.disabled', fontSize: '0.7rem' }}>
                  Seleziona i giocatori per vedere le statistiche aggregate
                </Typography>
              ) : (
                <>
                  {statsLoadingCount > 0 && (
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mb: 0.5 }}>
                      <CircularProgress size={10} />
                      <Typography variant="caption" sx={{ color: 'text.secondary', fontSize: '0.65rem' }}>
                        Caricamento {statsLoadingCount}…
                      </Typography>
                    </Box>
                  )}
                  <StatRow label="Giocatori" value={`${filledCount}/11`} />
                  <StatRow label="Presenze" value={aggregated.appareances.toLocaleString('it-IT')} loading={statsLoadingCount > 0} />
                  <StatRow label="Gol" value={aggregated.goalsScored.toLocaleString('it-IT')} loading={statsLoadingCount > 0} highlight />
                  {selectedEntries.some(({ slot }) => slot.key === 'gk') && (
                    <StatRow label="Gol subiti (POR)" value={aggregated.goalsConceded.toLocaleString('it-IT')} loading={statsLoadingCount > 0} />
                  )}
                  <Divider sx={{ my: 0.75 }} />
                  <Typography variant="caption" sx={{ fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '0.06em', display: 'block', mb: 0.5, fontSize: '0.6rem' }}>
                    Dettaglio
                  </Typography>
                  {selectedEntries.map(({ slot, player }) => {
                    const s = playerStats[String(player.id)];
                    const isGk = slot.key === 'gk';
                    return (
                      <Box
                        key={slot.key}
                        onClick={() => onSelectPlayer(player.id)}
                        sx={{
                          display: 'flex', alignItems: 'center', gap: 0.5, py: 0.3,
                          borderBottom: '1px solid rgba(0,0,0,0.04)', '&:last-child': { borderBottom: 'none' },
                          cursor: 'pointer', borderRadius: 0.5,
                          '&:hover': { bgcolor: 'rgba(8,45,104,0.06)' },
                        }}
                      >
                        <Chip label={slot.label} size="small" sx={{ fontSize: 8, height: 16, minWidth: 28, bgcolor: '#082D68', color: '#fff', fontWeight: 700 }} />
                        <Typography variant="caption" sx={{ flex: 1, fontSize: '0.68rem' }} noWrap>
                          {(player.name || '').split(' ')[0]}
                        </Typography>
                        {s ? (
                          <Box sx={{ display: 'flex', gap: 0.5, flexShrink: 0 }}>
                            <Typography variant="caption" sx={{ fontSize: '0.65rem', color: 'text.secondary' }}>
                              {s.appareances}
                            </Typography>
                            <Typography variant="caption" sx={{ fontSize: '0.65rem', color: isGk ? 'text.secondary' : '#CA2331', fontWeight: 700 }}>
                              {isGk ? `${s.goal}s` : `${s.goal}g`}
                            </Typography>
                          </Box>
                        ) : (
                          <CircularProgress size={8} />
                        )}
                      </Box>
                    );
                  })}
                </>
              )}
            </CardContent>
          </Card>

          {/* Seasons box */}
          {seasonCount > 0 && (
            <Card>
              <CardContent sx={{ py: '10px !important' }}>
                <Box sx={{ display: 'flex', alignItems: 'baseline', gap: 1, mb: 1 }}>
                  <Typography variant="caption" sx={{ fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '0.06em' }}>
                    Stagioni coinvolte
                  </Typography>
                  <Typography variant="caption" sx={{ color: 'text.disabled' }}>
                    {seasonCount}{statsLoadingCount > 0 ? '+' : ''} · {sortedYears[0]}–{sortedYears[seasonCount - 1]}
                  </Typography>
                </Box>
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {sortedYears.map(year => {
                    const count = yearPlayerCount.get(year) || 0;
                    const intensity = count / Math.max(filledCount, 1);
                    return (
                      <Box
                        key={year}
                        title={`${count} giocator${count === 1 ? 'e' : 'i'} attiv${count === 1 ? 'o' : 'i'}`}
                        sx={{
                          px: 0.8, py: 0.2, borderRadius: 1, cursor: 'default',
                          bgcolor: `rgba(8,45,104,${0.12 + intensity * 0.75})`,
                          border: '1px solid',
                          borderColor: `rgba(8,45,104,${0.15 + intensity * 0.4})`,
                        }}
                      >
                        <Typography sx={{ fontSize: '0.68rem', fontWeight: 600, color: intensity > 0.5 ? '#fff' : '#082D68', lineHeight: 1.4 }}>
                          {year}
                        </Typography>
                      </Box>
                    );
                  })}
                </Box>
              </CardContent>
            </Card>
          )}
          </Box>
        </Box>
      </Box>

      {/* Player picker */}
      <Dialog open={pickerOpen} onClose={() => setPickerOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', pb: 1 }}>
          <Box>
            <Typography variant="subtitle1" sx={{ fontWeight: 700 }}>
              {activeSlot ? `Seleziona ${activeSlot.label}` : 'Seleziona giocatore'}
            </Typography>
            {activeSlot && (
              <Typography variant="caption" sx={{ color: 'text.secondary' }}>
                Ruolo suggerito: {activeSlot.suggestedRole}
              </Typography>
            )}
          </Box>
          <IconButton size="small" onClick={() => setPickerOpen(false)}>
            <CloseIcon fontSize="small" />
          </IconButton>
        </DialogTitle>
        <DialogContent sx={{ pt: 1 }}>
          <TextField
            fullWidth size="small" placeholder="Cerca per nome…"
            value={search} onChange={e => setSearch(e.target.value)}
            autoFocus sx={{ mb: 1.5 }}
          />
          <Box sx={{ maxHeight: 420, overflowY: 'auto' }}>
            {search ? (
              allFiltered.length > 0
                ? allFiltered.map(p => <PlayerPickerRow key={p.id} player={p} onClick={() => handlePlayerSelect(p)} />)
                : <Typography variant="body2" sx={{ color: 'text.secondary', py: 2, textAlign: 'center' }}>Nessun risultato</Typography>
            ) : (
              <>
                <Typography variant="caption" sx={{ fontWeight: 700, color: 'primary.main', textTransform: 'uppercase', letterSpacing: '0.06em', display: 'block', mb: 0.5 }}>
                  Suggeriti · {activeSlot?.suggestedRole}
                </Typography>
                {suggested.map(p => <PlayerPickerRow key={p.id} player={p} onClick={() => handlePlayerSelect(p)} />)}
                <Divider sx={{ my: 1 }} />
                <Typography variant="caption" sx={{ fontWeight: 700, color: 'text.secondary', textTransform: 'uppercase', letterSpacing: '0.06em', display: 'block', mb: 0.5 }}>
                  Altri ruoli
                </Typography>
                {others.map(p => <PlayerPickerRow key={p.id} player={p} onClick={() => handlePlayerSelect(p)} />)}
              </>
            )}
          </Box>
        </DialogContent>
        {squad[activeSlot?.key] && (
          <DialogActions>
            <Button size="small" color="error" startIcon={<DeleteOutlineIcon />} onClick={handleRemoveFromPicker}>
              Rimuovi
            </Button>
          </DialogActions>
        )}
      </Dialog>

      {/* Reset confirm */}
      <Dialog open={confirmReset} onClose={() => setConfirmReset(false)} maxWidth="xs">
        <DialogTitle>Reset formazione?</DialogTitle>
        <DialogContent>
          <Typography variant="body2">Tutti i giocatori selezionati verranno rimossi.</Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setConfirmReset(false)}>Annulla</Button>
          <Button color="error" onClick={() => { setSquad({}); setConfirmReset(false); }}>Reset</Button>
        </DialogActions>
      </Dialog>

      {openPlayer && (
        <PlayerReport
          open={openPlayer}
          handleClose={() => { setOpenPlayer(false); setPlayerId(0); }}
          playerReport={playerReport}
          playerId={playerId}
        />
      )}

      <Footer />
    </Box>
  );
}
